clickhouse:index/role:Role.description:
You can use the *clickhouse_role* resource to manage custom RBAC roles in ClickHouse Cloud.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as clickhouse from "@pulumiverse/clickhouse";

const example = new clickhouse.Role("example", {
    name: "my-custom-role",
    policies: [
        {
            effect: "ALLOW",
            permissions: ["control-plane:organization:create-api-keys"],
            resources: ["organization/<org-id>"],
        },
        {
            effect: "ALLOW",
            permissions: ["control-plane:service:view-backups"],
            resources: ["instance/<service-id>"],
        },
        {
            effect: "ALLOW",
            permissions: ["sql-console:database:access"],
            resources: ["instance/<service-id>"],
            tags: {
                role: "sql-console-readonly",
            },
        },
    ],
});
const alice = clickhouse.getUser({
    email: "alice@example.com",
});
const exampleRoleAssignment = new clickhouse.RoleAssignment("example", {
    roleId: example.id,
    userIds: [alice.then(alice => alice.id)],
});
